T["11-wady-almlwk"] = [
 ("s1", "مَنْ دُفِنَ فِيهِ", [
  "تَذْكُرُ وِزَارَةُ السِّيَاحَةِ وَالآثَارِ أَنَّ مُعْظَمَ مُلُوكِ الأُسَرَاتِ الثَّامِنَةَ عَشْرَةَ وَالتَّاسِعَةَ عَشْرَةَ وَالعِشْرِينَ مِنَ الدَّوْلَةِ الحَدِيثَةِ دُفِنُوا فِي وَادٍ جَافٍّ عَلَى الضِّفَّةِ الغَرْبِيَّةِ لِطِيبَةَ القَدِيمَةِ، وَمِنْ هُنَا جَاءَ الِاسْمُ؛ لَكِنَّهُ لَيْسَ دَقِيقًا تَمَامًا، إِذْ دُفِنَ فِيهِ أَفْرَادٌ مِنَ العَائِلَةِ المَالِكَةِ غَيْرَ المُلُوكِ، وَبَعْضُ غَيْرِ المَلَكِيِّينَ وَإِنْ كَانُوا رَفِيعِي المُسْتَوَى.",
  "وَيَنْقَسِمُ الوَادِي إِلَى الشَّرْقِيِّ وَالغَرْبِيِّ، وَالشَّرْقِيُّ أَشْهَرُهُمَا، وَيَضُمُّ الوَادِي الغَرْبِيُّ عَدَدًا قَلِيلًا مِنَ المَقَابِرِ. وَيَضُمُّ الوَادِي إِجْمَالًا أَكْثَرَ مِنْ سِتِّينَ مَقْبَرَةً، بِالإِضَافَةِ إِلَى عِشْرِينَ مَقْبَرَةً غَيْرَ مُكْتَمِلَةٍ لَا تَزِيدُ عَلَى كَوْنِهَا حُفَرًا."]),
 ("s2", "لِمَاذَا هَذَا المَوْقِعُ", [
  "تَشْرَحُ الوِزَارَةُ أَنَّ المَوْقِعَ اخْتِيرَ بِعِنَايَةٍ عَلَى الضِّفَّةِ الغَرْبِيَّةِ لِأَنَّ مَعْبُودَ الشَّمْسِ يَنْزِلُ، يَمُوتُ، فِي الأُفُقِ الغَرْبِيِّ لِيُولَدَ مِنْ جَدِيدٍ وَيَتَجَدَّدَ فِي الأُفُقِ الشَّرْقِيِّ، وَلِهَذَا ارْتَبَطَ الغَرْبُ بِالمَفَاهِيمِ الجَنَائِزِيَّةِ. وَدُفِنَ مُلُوكُ الدَّوْلَةِ الحَدِيثَةِ تَحْتَ قِمَّةِ جُرْفٍ صَخْرِيٍّ هَرَمِيِّ الشَّكْلِ يُحِيطُ بِالوَادِي، وَكَانَ الهَرَمُ رَمْزًا لِلْبَعْثِ وَالحَيَاةِ الأَبَدِيَّةِ، وَكَانَتِ المِنْطَقَةُ وَالقِمَّةُ تَحْتَ سَيْطَرَةِ المَعْبُودَةِ حَتْحُورَ، سَيِّدَةِ الغَرْبِ."]),
]

T["08-tybh-alaqsr"] = [
 ("s1", "الأَسْمَاءُ وَالعَاصِمَةُ", [
  "تَذْكُرُ الوِزَارَةُ أَنَّ المَدِينَةَ عُرِفَتْ بِأَسْمَاءٍ عِدَّةٍ: سُمِّيَتْ وَاسِتْ، وَسَمَّاهَا الإِغْرِيقُ ثِيبْسَ عَلَى اسْمِ مَدِينَةٍ لَهُمْ فِي قَلْبِ اليُونَانِ وَمَيَّزُوهَا بِلَقَبِ ذَاتِ المِئَةِ بَابٍ، وَعُرِّبَ الِاسْمُ إِلَى طِيبَةَ. أَمَّا الأُقْصُرُ فَهُوَ جَمْعُ قَصْرٍ، أَطْلَقَهُ العَرَبُ عَلَيْهَا بَعْدَ فَتْحِ مِصْرَ سَنَةَ سِتِّ مِئَةٍ وَوَاحِدٍ وَأَرْبَعِينَ مِيلَادِيًّا حِينَ أَبْهَرَتْهُمْ مَعَابِدُهَا فَتَصَوَّرُوهَا قُصُورًا.",
  "وَفِي الدَّوْلَةِ القَدِيمَةِ صَارَتْ وَاسِتْ عَاصِمَةَ الإِقْلِيمِ الرَّابِعِ فِي مِصْرَ العُلْيَا وَمَرْكَزًا إِدَارِيًّا وَاقْتِصَادِيًّا، تُؤَكِّدُ أَهَمِّيَّتَهُ مَقَابِرُ حُكَّامِهِ. وَخِلَالَ عَصْرِ الِانْتِقَالِ الأَوَّلِ كَافَحَتِ الأُسْرَةُ الحَاكِمَةُ فِي طِيبَةَ لِإِعَادَةِ تَوْحِيدِ مِصْرَ، وَتَمَكَّنَ مُنْتَوْحُتِبُ الثَّانِي مِنْ إِعَادَةِ التَّوْحِيدِ، فَعَلَا شَأْنُ المَدِينَةِ لِتَكُونَ عَاصِمَةَ مِصْرَ."]),
 ("s2", "مَا تَحْضُنُهُ المَدِينَةُ", [
  "تَصِفُ الوِزَارَةُ الأُقْصُرَ بِأَنَّهَا أَشْبَهُ بِمَدِينَةٍ مَتْحَفِيَّةٍ تَحْتَضِنُ جَانِبًا كَبِيرًا مِنَ المَوَاقِعِ الأَثَرِيَّةِ المُهِمَّةِ فِي مِصْرَ وَالعَالَمِ. وَمِنْ مَوَاقِعِهَا الَّتِي لَهَا صَفَحَاتٌ مُسْتَقِلَّةٌ فِي المَوْسُوعَةِ: الكَرْنَكُ، وَمَعْبَدُ الأُقْصُرِ، وَالدَّيْرُ البَحْرِيُّ، وَوَادِي المُلُوكِ، وَمَدِينَةُ هَابُو."]),
]

T["14-mdynh-habw"] = [
 ("s1", "المَعْبَدُ وَصَاحِبُهُ", [
  "تَذْكُرُ وِزَارَةُ السِّيَاحَةِ وَالآثَارِ أَنَّ رَمْسِيسَ الثَّالِثَ بَنَى مَعْبَدَهُ الجَنَائِزِيَّ المَعْرُوفَ بِمَعْبَدِ مَدِينَةِ هَابُو، وَأَنَّهُ يُعَدُّ تُحْفَةً مِعْمَارِيَّةً لِجَمَالِهِ وَحَالَتِهِ الجَيِّدَةِ مِنَ الحِفْظِ، وَخُصِّصَ لِإِقَامَةِ الطُّقُوسِ الجَنَائِزِيَّةِ لَهُ وَلِشَعَائِرِ عِبَادَةِ آمُونَ، وَبُنِيَ وَفْقَ التَّقَالِيدِ المُعْتَادَةِ فِي عَصْرِهِ وَمُسْتَوْحًى إِلَى حَدٍّ كَبِيرٍ مِنْ مَعْبَدِ الرَّامِسِيُّومِ.",
  "وَتَصِفُ رَمْسِيسَ الثَّالِثَ بِأَنَّهُ مِنْ أَشْهَرِ مُلُوكِ الأُسْرَةِ العِشْرِينَ، خَاضَ حُرُوبًا كَثِيرَةً ضِدَّ اللِّيبِيِّينَ وَشُعُوبِ البَحْرِ شَهِدَتْ مِصْرُ بَعْدَهَا سَنَوَاتٍ مِنَ الرَّخَاءِ وَالِاسْتِقْرَارِ، ثُمَّ وَقَعَ فِي النِّهَايَةِ ضَحِيَّةَ مُؤَامَرَةٍ مِنَ الحَرِيمِ المَلَكِيِّ فِي أَوَاخِرِ عَهْدِهِ."]),
 ("s2", "التَّخْطِيطُ", [
  "يَذْكُرُ المَصْدَرُ أَنَّ المَعْبَدَ يُحِيطُ بِهِ سُورٌ ضَخْمٌ مِنَ الطُّوبِ اللَّبِنِ بِهِ حُجْرَتَانِ لِلحِرَاسَةِ، وَيَتَوَسَّطُهُ بَوَّابَةٌ عَظِيمَةٌ يَكْتَنِفُهَا بُرْجَانِ ذَوَا شُرُفَاتٍ تُعْرَفُ بِبَوَّابَةِ رَمْسِيسَ الثَّالِثِ، وَتَقَعُ فِي الجِهَةِ الشَّرْقِيَّةِ، وَكَانَ لَهَا مَثِيلٌ فِي الغَرْبِيَّةِ تَهَدَّمَ. وَتُؤَدِّي البَوَّابَةُ الشَّرْقِيَّةُ إِلَى الصَّرْحِ الأَوَّلِ ثُمَّ الفِنَاءِ الأَوَّلِ ثُمَّ الصَّرْحِ الثَّانِي وَالفِنَاءِ الثَّانِي ثُمَّ ثَلَاثِ قَاعَاتٍ لِلْأَعْمِدَةِ وَمَجْمُوعَةٍ مِنَ المَقَاصِيرِ ثُمَّ قُدْسِ الأَقْدَاسِ وَخَلْفَهُ غُرَفٌ. وَيَضُمُّ المَعْبَدُ أَيْضًا بَقَايَا القَصْرِ المَلَكِيِّ وَمَخَازِنَ وَمَبَانِيَ لِإِدَارَةِ المَعْبَدِ وَإِصْطَبْلَاتٍ."]),
]

T["13-abw-smbl"] = [
 ("s1", "المَعْبَدُ الكَبِيرُ", [
  "تَذْكُرُ وِزَارَةُ السِّيَاحَةِ وَالآثَارِ أَنَّ مَعْبَدَ أَبُو سِمْبِلَ الكَبِيرَ فِي النُّوبَةِ قُرْبَ الحُدُودِ الجَنُوبِيَّةِ لِمِصْرَ مِنْ أَكْثَرِ مَعَالِمِ مِصْرَ رَوْعَةً، بَنَاهُ رَمْسِيسُ الثَّانِي مِنَ الأُسْرَةِ التَّاسِعَةَ عَشْرَةَ، وَنُحِتَ كَامِلًا فِي الجَبَلِ حَوَالِيَ عَامِ أَلْفٍ وَمِئَتَيْنِ وَأَرْبَعَةٍ وَسِتِّينَ قَبْلَ المِيلَادِ. وَيَشْتَهِرُ بِتَمَاثِيلِهِ الأَرْبَعَةِ الضَّخْمَةِ الجَالِسَةِ الَّتِي تُزَيِّنُ وَاجِهَتَهُ، وَالَّتِي انْهَارَ أَحَدُهَا بِسَبَبِ زِلْزَالٍ قَدِيمٍ وَلَا تَزَالُ بَقَايَاهُ عَلَى الأَرْضِ.",
  "وَتَقِفُ تَمَاثِيلُ المَلِكِ الضَّخْمَةُ عَلَى جَانِبَيِ الصَّالَةِ الرَّئِيسِيَّةِ المُؤَدِّيَةِ إِلَى قُدْسِ الأَقْدَاسِ، حَيْثُ تَجْلِسُ أَرْبَعَةُ مَعْبُودَاتٍ: آمُونُ رَعُ، وَرَعُ حُورُ آخْتِي، وَبْتَاحُ، وَرَمْسِيسُ الثَّانِي بِصِفَتِهِ مَعْبُودًا. وَبُنِيَ المَعْبَدُ بِدِقَّةٍ بِحَيْثُ تَدْخُلُ أَشِعَّةُ الشَّمْسِ يَوْمَيْنِ فِي السَّنَةِ، فِي الثَّانِي وَالعِشْرِينَ مِنْ فِبْرَايِرَ وَالثَّانِي وَالعِشْرِينَ مِنْ أُكْتُوبَرَ، وَتَعْبُرُ الصَّالَةَ وَتُضِيءُ التَّمَاثِيلَ فِي عُمْقِ المَعْبَدِ إِلَّا تِمْثَالَ بْتَاحَ."]),
 ("s2", "المَعْبَدُ الصَّغِيرُ وَنَقْلُ المَعْبَدَيْنِ", [
  "يَذْكُرُ المَصْدَرُ أَنَّ إِلَى الشَّمَالِ مَعْبَدًا آخَرَ مَحْفُورًا فِي الصَّخْرِ يُعْرَفُ بِالمَعْبَدِ الصَّغِيرِ، مُكَرَّسٌ لِحَتْحُورَ وَلِلزَّوْجَةِ المَلَكِيَّةِ العُظْمَى نَفَرْتَارِي، وَعَلَى وَاجِهَتِهِ تَقِفُ تَمَاثِيلُهَا الضَّخْمَةُ بِنَفْسِ حَجْمِ تَمَاثِيلِ زَوْجِهَا، فِي مِثَالٍ نَادِرٍ.",
  "وَنُقِلَ المَعْبَدَانِ مِنْ مَوْضِعِهِمَا الأَصْلِيِّ سَنَةَ أَلْفٍ وَتِسْعِ مِئَةٍ وَثَمَانٍ وَسِتِّينَ بَعْدَ بِنَاءِ السَّدِّ العَالِي الَّذِي هَدَّدَ بِإِغْرَاقِهِمَا، وَأُنْجِزَ النَّقْلُ بِجُهُودٍ دَوْلِيَّةٍ قَادَتْهَا اليُونِسْكُو."]),
]

for slug, secs in T.items():
    data = dict(slug=slug, kind="sites", narrated_only=True,
                sections=[dict(id=i, title=t, parts=p) for i, t, p in secs])
    p = os.path.join(ROOT, "audio", "scripts", "sites-%s.tashkeel.json" % slug)
    open(p, "w", encoding="utf-8").write(json.dumps(data, ensure_ascii=False, indent=1))
    print("wrote", os.path.basename(p), sum(len(x) for _, _, ps in secs for x in ps), "chars")
